package dev.inkstone.core.calc.num

import kotlin.test.Test
import kotlin.test.assertEquals

/**
 * A seeded random sweep — research 07 T11's "~200 random arguments", run against Python rather
 * than the calculator: 30 random 15-digit arguments for each of 13 functions and for `xʸ`,
 * answered by the same Python 3.14 `decimal` implementations as `DecMathReferenceTest` at 130
 * digits and rounded once, half away from zero. Generated by `sweepgen.py` (seed 1103) in the
 * session scratchpad and pasted unchanged.
 *
 * Every row demands exact equality: this is the evidence for "correctly rounded in practice".
 * When T11 is run on the emulator, the calculator's own last digits go in a separate table.
 */
class DecMathSweepTest {
    private class Row(val function: String, val argument: String, val expected: String)

    private val functions: Map<String, (String) -> Dec?> = mapOf(
        "exp" to { a -> DecMath.exp(d(a)) }, "ln" to { a -> DecMath.ln(d(a)) },
        "log10" to { a -> DecMath.log10(d(a)) }, "sqrt" to { a -> DecMath.sqrt(d(a)) },
        "cbrt" to { a -> DecMath.cbrt(d(a)) }, "sin" to { a -> DecMath.sin(d(a)) },
        "cos" to { a -> DecMath.cos(d(a)) }, "tan" to { a -> DecMath.tan(d(a)) },
        "atan" to { a -> DecMath.atan(d(a)) }, "asin" to { a -> DecMath.asin(d(a)) },
        "sinh" to { a -> DecMath.sinh(d(a)) }, "tanh" to { a -> DecMath.tanh(d(a)) },
        "asinh" to { a -> DecMath.asinh(d(a)) },
        "pow" to { a -> a.split(';').let { (x, y) -> DecMath.pow(d(x), d(y)) } },
    )

    @Test
    fun `random arguments are correctly rounded`() {
        val wrong = rows.filter { functions.getValue(it.function)(it.argument) != d(it.expected) }
        val report = wrong.joinToString("\n") {
            "${it.function}(${it.argument}) = ${functions.getValue(it.function)(it.argument)}, want ${it.expected}"
        }
        assertEquals(0, wrong.size, report)
    }

